from collections import defaultdict

class Solution:
    def sortMatrix(self, grid):
        n = len(grid)
        diagonals = defaultdict(list)

        # Step 1: collect diagonal elements using (i - j) as the key
        for i in range(n):
            for j in range(n):
                diagonals[i - j].append(grid[i][j])

        # Step 2: sort so that pop() yields the next required value
        for key in diagonals:
            if key >= 0:
                # bottom-left (incl. main): non-increasing -> pop largest first
                diagonals[key].sort()
            else:
                # top-right: non-decreasing -> pop smallest first
                diagonals[key].sort(reverse=True)

        # Step 3: put the values back in row-major order
        for i in range(n):
            for j in range(n):
                grid[i][j] = diagonals[i - j].pop()

        return grid
